const inputItems = $input.all();

return inputItems.map(item => {
  const data = item.json;

  // 1. Detectar si los datos vienen de un Webhook (dentro de "body") o directos
  const payload = data.body ? data.body : data;

  // 2. Extraer variables clave desde el payload correcto
  const isPrivateIP = payload.threat_intel?.is_private_ip || false;
  const category = payload.category || 'unknown';
  const riskScore = Number(payload.risk_score) || 0;

  // Valores por defecto
  let blockDecision = 'ignore';
  let reason = 'Score de riesgo insuficiente para tomar acción.';
  let firewallAction = 'none';

  // --- 3. REGLAS DE EXCLUSIÓN ESTRICTAS (WHITELIST) ---
  if (isPrivateIP) {
    reason = `IP Privada/Interna detectada (${payload.source_ip}). Las IPs de red local o contenedores no se bloquean.`;
  } 
  else if (category === 'system' || category === 'maintenance') {
    reason = `Evento de categoría '${category}'. Son errores del sistema, no ataques perimetrales.`;
  }

  // --- 4. LÓGICA DE BLOQUEO ---
  else if (riskScore >= 60) {
    blockDecision = 'block';
    reason = `Riesgo detectado (Score: ${riskScore}). Se requiere bloqueo en el firewall.`;
    firewallAction = 'block';
  }

  // 5. Preparar el payload de salida aplanado (sin el "body" estorbando)
  const result = {
    ...payload, 
    block_decision: blockDecision,
    reason: reason,
    firewall_action: firewallAction
  };

  // 6. Configurar metadatos si la decisión es BLOQUEAR
  if (blockDecision === 'block') {
    result.jail_type = 'soar';
    result.block_timestamp = new Date().toISOString();

    const baseBanDurationMinutes = 1; 
    const blockedUntil = new Date();
    blockedUntil.setMinutes(blockedUntil.getMinutes() + baseBanDurationMinutes);

    result.blocked_until = blockedUntil.toISOString();
  }

  return { json: result };
});

// Forzamos a n8n a leer del nodo original de decisión
const result = $('¿Bloquear?').item.json;

const isBlocked = result.block_decision === 'block';

const report = {
  type: 'ip_block_event',
  timestamp: new Date().toISOString(),
  action: 'ip_blocking',
  status: isBlocked ? 'blocked' : 'not_blocked',
  severity: result.severity,        
  category: result.rule_name,

  // 🛠️ ALIAS PARA EL DASHBOARD: Mapeamos los campos exactos que pide el gráfico roto
  ip_address: result.source_ip, 
  is_active: isBlocked, // Mandamos true si fue bloqueado, false si no

  details: {
    ip: result.source_ip,
    threat_score: result.risk_score,
    reason: result.reason || 'Alerta crítica detectada', 
    blocked_until: result.blocked_until,
    firewall_executed: true          
  },
  workflow: 'auto_blocking_v1'
};

console.log('Reporte con campos de compatibilidad:', JSON.stringify(report, null, 2));

return [{ json: report }];
